function parsePosibleJson(valor) {
  if (valor === undefined || valor === null || valor === '') return {};
  if (typeof valor === 'object') return valor;
  if (typeof valor === 'string') {
    const limpio = valor.trim();
    if (!limpio) return {};
    try { return JSON.parse(limpio); } catch (e) { return {}; }
  }
  return {};
}
function primero(payload) {
  if (Array.isArray(payload)) return payload[0] || {};
  return payload || {};
}
function intOrNull(v) {
  if (v === undefined || v === null || v === '') return null;
  const n = Number.parseInt(String(v), 10);
  return Number.isFinite(n) ? n : null;
}
function bool(v, defecto = false) {
  if (v === undefined || v === null || v === '') return defecto;
  if (typeof v === 'boolean') return v;
  const t = String(v).trim().toLowerCase();
  if (['true', '1', 'si', 's?', 'yes', 'y'].includes(t)) return true;
  if (['false', '0', 'no', 'n'].includes(t)) return false;
  return defecto;
}
function ymd(date) {
  return date.toISOString().slice(0, 10);
}
function fechaBase(valor) {
  if (!valor) return new Date();
  const d = new Date(String(valor));
  if (Number.isNaN(d.getTime())) throw new Error(`fecha_proceso invalida: ${valor}`);
  return d;
}

const raw = $input.first()?.json || {};
const body = primero(parsePosibleJson(raw.body ?? raw));
const payload = Object.keys(body).length ? body : raw;
const dias = intOrNull(payload.dias_a_sumar ?? payload.simular_dias) ?? 0;
const base = fechaBase(payload.fecha_proceso ?? payload.fecha ?? null);
base.setDate(base.getDate() + dias);

return [{
  json: {
    modo: raw.webhookUrl ? 'webhook_simulacion' : 'schedule_nocturno',
    fecha_proceso: ymd(base),
    id_alumno: intOrNull(payload.id_alumno),
    id_mesociclo: intOrNull(payload.id_mesociclo),
    forzar_recalculo: bool(payload.forzar_recalculo, false),
    dry_run: bool(payload.dry_run, false)
  }
}];

const limpiar = valor => String(valor || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const canonTipo = tipo => limpiar(tipo).replace('SECUNDARIO_RECOMENDADO', 'SECUNDARIO').replace('TERCEARIO', 'TERCIARIO').replace('TRECERIO', 'TERCIARIO');
function esMono(row) {
  const tipo = canonTipo(row.tipo_slot);
  const multiMono = limpiar(row.multi_mono);
  return tipo === 'TERCIARIO' || tipo === 'DEBILIDAD' || multiMono.includes('MONO');
}
function clamp(n, min, max) { return Math.max(min, Math.min(max, n)); }
function asNumber(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}
function parseHist(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v === 'object') return Array.isArray(v) ? v : [];
  try { return JSON.parse(v); } catch (e) { return []; }
}
function pctDescarga(nivel, mono) {
  if (nivel === 'P2' && !mono) return 0.95;
  if (['I1', 'I2'].includes(nivel)) return 0.975;
  return 0.90;
}
function pctSubida(nivel) {
  return nivel === 'I2' ? 1.025 : 1.05;
}
function descanso(rirMin, rirMax, multi, aerobico) {
  if (aerobico) return 0;
  const rir = Math.round((asNumber(rirMin, 4) + asNumber(rirMax, 4)) / 2);
  if (rir >= 3) return multi ? 90 : 60;
  if (rir === 2) return multi ? 120 : 90;
  if (rir === 1) return multi ? 150 : 90;
  return multi ? 180 : 120;
}
function rangoInicial(nivel, mono) {
  if (nivel === 'P2') return mono ? [10, 12] : [8, 10];
  if (nivel === 'P1') return mono ? [12, 15] : [10, 12];
  return mono ? [10, 12] : [8, 12];
}
function thresholdBajo(nivel, mono, min, max) {
  if (nivel === 'P2' && !mono && min === 8 && max === 10) return 9;
  return 11;
}
function dosFallos(row, min, max, nivel, mono) {
  const hist = parseHist(row.ultimas_dos_semanas).slice(0, 2);
  if (hist.length < 2) return false;
  const threshold = (min <= 8 && max <= 10 && nivel === 'P2' && !mono) ? 9 : (max >= 15 ? 13.5 : 11);
  return hist.every(x => asNumber(x.reps_promedio, 0) <= threshold);
}

return $input.all().map(item => {
  const r = item.json;
  const nivel = r.nivel_experiencia === 'P3' ? 'I1' : (r.nivel_experiencia || 'P1');
  const tipo = canonTipo(r.tipo_slot);
  const aerobico = tipo === 'AEROBICO';
  const isometrico = limpiar(r.patron_movimiento).includes('ISOMETR') || limpiar(r.nombre_ejercicio).includes('ISOMETR');
  const banda = limpiar(r.equipo_necesario).includes('BANDA') || limpiar(r.accesorio).includes('BANDA');
  const mono = esMono(r);
  const multi = !mono;
  let series = clamp(asNumber(r.series_actuales, 3), 0, 4);
  let repsMin = asNumber(r.reps_min_actual, rangoInicial(nivel, mono)[0]);
  let repsMax = asNumber(r.reps_max_actual, rangoInicial(nivel, mono)[1]);
  let peso = asNumber(r.peso_referencia, asNumber(r.peso_actual, 0));
  let duracion = r.duracion_objetivo_min ?? null;
  let tempo = r.tempo || '1-1-2';
  let estado = 'sin_cambios';
  let comentario = `Actualizador nocturno: semana ${r.semana_origen} -> ${r.semana_target}; completados ${r.entrenamientos_completados}/${r.entrenamientos_esperados}`;
  const promedio = asNumber(r.reps_promedio_semana, 0);

  if (aerobico) {
    series = 0;
    repsMin = 0;
    repsMax = 0;
    peso = 0;
    duracion = 10;
    tempo = 'CONTINUO';
    estado = 'aerobico_10_min';
    comentario += nivel === 'P1' ? ' | Aerobico suave 10 minutos' : ' | Aerobico media intensidad 10 minutos';
  } else if (isometrico) {
    const baseSeg = repsMax > 0 ? repsMax : 20;
    const realizadoSeg = asNumber(r.duracion_realizada_min, 0) * 60;
    const cumple = realizadoSeg >= baseSeg;
    const siguienteSeg = cumple ? clamp(baseSeg + 5, 15, 60) : clamp(baseSeg - 5, 15, 60);
    repsMin = siguienteSeg;
    repsMax = siguienteSeg;
    series = cumple ? clamp(series, 3, 4) : clamp(series + 1, 3, 4);
    tempo = 'ISOMETRICO';
    duracion = Math.round(siguienteSeg / 60);
    estado = cumple ? 'isometrico_sube_5s' : 'isometrico_baja_5s_o_sube_series';
    comentario += ' | Escala isometrica provisional: 15-60 segundos en saltos de 5s';
  } else if (promedio > 0) {
    const p2MultiBajo = nivel === 'P2' && !mono && repsMin === 8 && repsMax === 10;
    const rangoBajo = p2MultiBajo || (repsMin === 10 && repsMax === 12);
    const rangoAlto = (repsMin === 12 && repsMax === 15) || (nivel === 'P2' && !mono && repsMin === 10 && repsMax === 12);
    const falloDoble = dosFallos(r, repsMin, repsMax, nivel, mono);

    if (rangoBajo) {
      const threshold = thresholdBajo(nivel, mono, repsMin, repsMax);
      if (promedio >= threshold) {
        [repsMin, repsMax] = (nivel === 'P2' && !mono) ? [10, 12] : [12, 15];
        estado = 'sube_rango_repeticiones';
      } else if (falloDoble) {
        peso = peso > 0 ? peso * pctDescarga(nivel, mono) : 0;
        estado = 'descarga_por_dos_fallos';
      } else {
        estado = 'mantener_por_primer_fallo';
      }
    } else if (rangoAlto) {
      const threshold = repsMax === 15 ? 13.5 : 11;
      if (promedio > threshold) {
        if (series < 4) {
          series += 1;
          estado = 'sube_serie';
        } else {
          peso = peso > 0 ? peso * pctSubida(nivel) : 0;
          [repsMin, repsMax] = (nivel === 'P2' && !mono) ? [8, 10] : [10, 12];
          estado = 'sube_carga_y_reinicia_rango';
        }
      } else if (falloDoble) {
        if (series < 4) {
          series += 1;
          [repsMin, repsMax] = (nivel === 'P2' && !mono) ? [8, 10] : [10, 12];
          estado = 'sube_serie_y_reinicia_rango_por_dos_fallos';
        } else {
          peso = peso > 0 ? peso * pctDescarga(nivel, mono) : 0;
          [repsMin, repsMax] = (nivel === 'P2' && !mono) ? [8, 10] : [10, 12];
          estado = 'descarga_y_reinicia_rango_por_dos_fallos';
        }
      } else {
        estado = 'mantener_rango_alto_por_primer_fallo';
      }
    }
    comentario += ` | promedio reps ${promedio.toFixed(1)} | estado ${estado}`;
  }

  if (banda) comentario += ' | Bandas: pendiente tabla oficial de colores/resistencias';

  const descansoSeg = descanso(r.rir_objetivo_min, r.rir_objetivo_max, multi, aerobico);
  return {
    json: {
      ...r,
      series_nueva: series,
      reps_min_nueva: repsMin,
      reps_max_nueva: repsMax,
      peso_nuevo: Number(peso || 0).toFixed(2),
      tempo_nuevo: tempo,
      descanso_seg_nuevo: descansoSeg,
      duracion_objetivo_min_nueva: duracion,
      estado_microciclo_nuevo: estado,
      comentario_nuevo: comentario
    }
  };
});

const items = $input.all().map(i => i.json);
return [{
  json: {
    actualizados: items.length,
    bloques: items,
    mensaje: items.length ? 'Microciclos actualizados' : 'No hubo bloques elegibles para actualizar'
  }
}];
